def rle_decode(s: str) -> str:
    result = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '#':
            raise ValueError("'#' not preceded by a character")
        if i + 1 < n and s[i+1] == '#':
            j = i + 2
            k = j
            while k < n and s[k].isdigit():
                k += 1
            if k == j:
                raise ValueError("'#' not followed by at least one digit")
            count = int(s[j:k])
            if count < 4:
                raise ValueError("count below 4")
            result.append(c * count)
            i = k
        else:
            result.append(c)
            i += 1
    return ''.join(result)
